 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [[0] * (3 * w) for _ in range(3 * h)]
    for tile_r in range(3):
        for tile_c in range(3):
            flip_ud = tile_r != 1
            flip_lr = tile_c != 1
            for r in range(h):
                for c in range(w):
                    rr = h - 1 - r if flip_ud else r
                    cc = w - 1 - c if flip_lr else c
                    out[tile_r * h + r][tile_c * w + c] = grid[rr][cc]
    return out
